<template><el-card><div class="toolbar"><el-input v-model="q" placeholder="搜索学号" clearable/><el-select v-model="status" placeholder="全部状态" clearable><el-option label="待人工审核" value="review"/><el-option label="审核通过待交付" value="approved"/></el-select><el-button @click="selectAll">全选筛选结果</el-button><el-button type="success" @click="batch('approved')">批量通过</el-button><el-button type="danger" @click="batch('rejected')">批量退回</el-button></div><el-table :data="filtered" @selection-change="rows=$event" row-key="id"><el-table-column type="selection" width="50"/><el-table-column prop="id" label="学号"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="open(row.id)">查看流程/审核</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" :title="detail?.id"><el-descriptions v-if="detail" :column="1"><el-descriptions-item label="状态">{{detail.status}}</el-descriptions-item><el-descriptions-item label="修订号">{{detail.revision}}</el-descriptions-item><el-descriptions-item label="版本记录"><pre>{{JSON.stringify(detail.history,null,2)}}</pre></el-descriptions-item></el-descriptions><el-button type="success" @click="review('approved')">审核通过</el-button><el-button type="danger" @click="review('rejected')">退回</el-button><el-button @click="replace">照片替换流程</el-button></el-dialog></el-card></template><script setup>import{ref,computed}from'vue';const props=defineProps({students:Array});const emit=defineEmits(['refresh','message']);const q=ref(''),status=ref(''),rows=ref([]),dialog=ref(false),detail=ref(null);const filtered=computed(()=>props.students.filter(x=>(!q.value||x.id.includes(q.value))&&(!status.value||x.status===status.value)));const selectAll=()=>rows.value=filtered.value;async function batch(decision){const ids=rows.value.filter(x=>x.status==='review').map(x=>x.id);if(!ids.length)return emit('message','请先选择待人工审核学生');const r=await fetch('/api/v1/reviews/batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_ids:ids,decision,reason:''})});emit('message',r.ok?'批量审核完成':'批量审核失败');emit('refresh')}async function open(id){detail.value=await(await fetch('/api/v1/students/'+encodeURIComponent(id))).json();dialog.value=true}async function review(decision){if(!detail.value)return;const result=detail.value.results?.at(-1);if(!result)return emit('message','没有可审核成片');const r=await fetch('/api/v1/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_id:detail.value.id,result_id:result.id,decision,expected_revision:detail.value.revision,reason:''})});emit('message',r.ok?'审核已保存':'审核失败');dialog.value=false;emit('refresh')}async function replace(){await fetch('/api/v1/students/'+detail.value.id+'/replacement',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:'照片替换'})});emit('message','已启动替换流程')}</script>